"""Rewrite docs/space-budget.md from the fit model."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from mechanical.pendant_mech import stack as S          # noqa: E402
from mechanical.pendant_mech.checks import full_report  # noqa: E402

rep = full_report()
o = ["# Space budget", "",
     "Generated by `tools/space_budget.py` from the model in `mechanical/`. Lengths in millimetres.",
     "Part sizes come from `parts/parts.yaml`; several are still unverified there, and the cells",
     "are trade size codes with estimated capacities, not a supplier's drawing.", "",
     "## Rules the model applies", "",
     "- The case, its cavity and the board are ellipses with one centre. A part fits when all four of",
     "  its corners are inside the ellipse; a cell fits when its corners, with the gap around it, clear the rim.",
     "- From the chest outwards: back cover, adhesive, cell, gap, board, parts, gap, stone. The stone is flat",
     "  underneath and domed on top, so the height is the one at the centre; the rim is lower by the dome.",
     f"- Cell: {S.SWELL:.0%} thickness growth allowed for; {S.CELL_GAP} around it; {S.BOARD_CLEAR} between the swollen cell and the board.",
     "  It lies centred, so that the oval takes the least from its corners.",
     "- The microphones are bottom-port parts: they hang under the board, one at each tip of the oval, with",
     f"  their hole through it, {S.MIC_TIP} from the tip. The pads of the cell tabs sit between the cell and microphone B.",
     f"- The two microphones are at least {S.MIN_MIC_DISTANCE:.0f} apart.",
     "- The strip the cell leaves along one long side holds, under the board, the side-push switch and the",
     "  four spring contacts. The same strip on the other side is the antenna's: no copper there on any layer.",
     "- Every part the case decides has a place on the board and none overlaps another or a keep-out (antenna",
     "  edge, microphone gaskets). The two QFN chips keep "
     f"{S.FINE_PITCH_MARGIN} clear around them.",
     f"- The other parts are counted here by area, each with {S.PART_SPACING} of spacing, and may take at most {S.PACKING:.0%} of the",
     "  free board. Their actual places are in the board file; nothing here checks that the tracks can be routed.", ""]
for key, e in rep["envelopes"].items():
    adopted = " (adopted)" if key == rep["adopted"] else ""
    o += [f"## Envelope {e['envelope']}{adopted}: {e['case'][0]} x {e['case'][1]} x {e['case'][2]}", "",
          f"**Result: {'everything fits' if e['ok'] else 'does not fit: ' + '; '.join(e['problems'])}.**", "",
          "| Layer | Thickness |", "| --- | --- |"]
    o += [f"| {k} | {v} |" for k, v in e["stack"].items()]
    c, r, a, m = e["cell"], e["cell_room"], e["area"], e["mass"]
    o += ["", f"- **Height**: {e['case'][2]} at the centre of the stone, {e['rim_height']} at the rim.",
          f"- **Room for the cell**: {r['length']} x {r['width']} x {r['thickness']} (thickness before swelling), less what the oval takes at the corners."]
    if c:
        o += [f"- **Cell**: {c['mpn']}, {c['size'][0]} x {c['size'][1]} x {c['size'][2]}, about {c['capacity_mah']} mAh. "
              f"Spare: {c['spare_length']} in length, {c['spare_width']} in width, {c['spare_height']} in height.",
              f"- **Under the board**: {c['board_to_back']} to the back cover, which is the height the spring contacts must span."]
    o += [f"- **Board**: an ellipse {e['board'][0]} x {e['board'][1]}, {a['board']} mm2. Large parts and keep-outs take {a['large_parts_and_keepouts']}; "
          f"the {a['small_parts']} small parts need {a['small_parts_need']}, {a['share_of_free']:.0%} of what is free.",
          f"- **Microphones**: {e['mic_distance']} apart.",
          f"- **Mass** (estimate): titanium rim {m['rim_g']} g, resin back {m['back_g']} g, glass stone {m['stone_g']} g, "
          f"board {m['board_g']} g, cell {m['cell_g']} g, about {m['total_g_estimate']} g without the chain.",
          f"- Drawings: [board from the front](../mechanical/out/plan-{key}.svg), [section](../mechanical/out/section-{key}.svg).", ""]
o += ["## What a larger case buys", "",
      f"Case {rep['envelopes']['A']['case'][0]} long, as envelope A. The cell is the best in `parts/parts.yaml` that fits.", "",
      "| Width | Height | Room for the cell | Best cell | Capacity |", "| --- | --- | --- | --- | --- |"]
for row in rep["size_sweep"]:
    r = row["room"]
    o.append(f"| {row['case'][1]} | {row['case'][2]} | {r['length']} x {r['width']} x {r['thickness']} | "
             f"{row['best_cell'] or 'none'} | {str(row['capacity_mah']) + ' mAh' if row['best_cell'] else ''} |")
o += ["", "Width is what an oval gives a cell: every cell in the list is 25 long, and the case is already long",
      "enough for it. Half a millimetre less height costs 20 mAh; the thicker cells only fit the wider cases.", ""]
(ROOT / "docs" / "space-budget.md").write_text("\n".join(o))
print("docs/space-budget.md written")
